style.css:
@-moz-document domain("pw.live") {
/* ===== GLOBAL ===== */

    html,
    body,
    #root {
        background: #101214 !important;
        color: #e6e6e6 !important;
    }

    * {
        box-shadow: none !important;
        scrollbar-color: #3a3d42 #101214 !important;
    }

    /* ===== SIDEBAR ===== */

    aside,
    nav {
        background: #0c0e10 !important;
        border-color: #202328 !important;
    }

    aside *,
    nav * {
        color: #b5b9bf !important;
    }

    /* ===== MAIN CONTENT ===== */

    main {
        background: #101214 !important;
    }

    /* ===== CARDS ===== */

    [class*="card"],
    [class*="Card"] {
        background: #17191d !important;
        border: 1px solid #25282d !important;
        border-radius: 7px !important;
    }

    [class*="card"]:hover,
    [class*="Card"]:hover {
        background: #1c1f24 !important;
        border-color: #353941 !important;
    }

    /* ===== TEXT ===== */

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        color: #f1f1f1 !important;
    }

    p,
    span,
    label {
        color: #b8bcc2 !important;
    }

    /* ===== LINKS ===== */

    a {
        color: #aaa3ff !important;
    }

    a:hover {
        color: #c5c0ff !important;
    }

    /* ===== BUTTONS ===== */

    button {
        background: #191c21 !important;
        color: #dedfe3 !important;
        border: 1px solid #292d33 !important;
        border-radius: 6px !important;
    }

    button:hover {
        background: #22262c !important;
    }

    /* ===== INPUTS ===== */

    input,
    textarea,
    select {
        background: #15171a !important;
        color: #e5e5e5 !important;
        border: 1px solid #292d33 !important;
    }

    /* ===== SEPARATORS ===== */

    hr {
        border-color: #24272c !important;
    }

    /* ===== IMAGES ===== */

    img {
        filter: none !important;
    }

    /* ===== TOOLTIP ===== */

    [role="tooltip"] {
        background: #202328 !important;
        color: #eeeeee !important;
        border: 1px solid #343840 !important;
    }
}
